function admin_header(string $title,string $active=''):void{ $items=['index.php'=>'Dashboard','patients.php'=>'Patients','visits.php'=>'Visits','appointments.php'=>'Appointments','admissions.php'=>'Admissions','wards.php'=>'Wards & Beds','doctors.php'=>'Doctors & Staff','laboratory.php'=>'Laboratory','pharmacy.php'=>'Pharmacy','prescriptions.php'=>'Prescriptions','billing.php'=>'Billing','reports.php'=>'Reports','messages.php'=>'Messages','services.php'=>'Services','departments.php'=>'Departments','settings.php'=>'Settings','audit.php'=>'Audit Log']; echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).' | Access Hospital</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><header class="top"><div class="brand"><span>+</span><div><strong>Access Hospital</strong><small>Hospital Management System</small></div></div><div><a href="../index.html">Website</a> <a href="logout.php">Logout</a></div></header><div class="shell"><aside><nav>'; foreach($items as $u=>$n){echo '<a class="'.($active===$u?'active':'').'" href="'.$u.'">'.$n.'</a>';} echo '</nav></aside><main>'; if($m=flash()){echo '<div class="flash">'.e($m).'</div>';}}
function admin_footer():void{echo '</main></div></body></html>';}
